// The /docs registry readers (card t_45fd1bee).
//
// `docsNav.gen.ts` is the DATA — generated by web/scripts/docsNav.mjs from the page
// files and the authored `NAV_GROUPS` table in app/docs/layout.tsx. This module is the
// small set of lookups the chrome needs on top of it, kept hand-written so the
// generated file stays a plain array:
//
//   docsBreadcrumb(path)    the trail every page renders above its <h1>
//   docsPager(path)         the previous/next pair, in sidebar reading order
//   relatedGuides(path)     the screenshot guides for a product page
//   relatedProducts(path)   the product pages a guide belongs to (the reverse mapping)
//
// WHY THE ORDER IS THE SIDEBAR ORDER. The card's requirement is that 30 pages are
// readable end to end: "next" follows the nav the reader is looking at, so a page's
// successor is the next row in `DOCS_NAV` — including the eight guides, which sit
// immediately after the Screenshot-guides index they belong to.

import { DOCS_NAV, type DocsNavEntry } from "./docsNav.gen.ts";

export { DOCS_NAV };
export type { DocsNavEntry, DocsNavKind, DocsNavLayer } from "./docsNav.gen.ts";

const BY_PATH = new Map(DOCS_NAV.map((entry) => [entry.path, entry]));

/** The registry entry for a route, or undefined for a route outside /docs. */
export function docsEntry(path: string): DocsNavEntry | undefined {
  return BY_PATH.get(path);
}

export type DocsCrumb = { label: string; href?: string };

/**
 * The breadcrumb trail for a page: Home › Docs › <section> › <page>.
 *
 * The middle layer is the sidebar group (`Workspaces`, `Sales & payments`, …), or the
 * layer name itself for Reference, where the group IS the layer. Learn pages do not add
 * a "Start here" crumb — it says nothing the page title does not.
 */
export function docsBreadcrumb(path: string): DocsCrumb[] {
  const trail: DocsCrumb[] = [{ label: "Home", href: "/" }];
  if (path === "/docs") {
    trail.push({ label: "Docs" });
    return trail;
  }
  const entry = docsEntry(path);
  if (!entry) return trail;
  trail.push({ label: "Docs", href: "/docs" });
  if (entry.layer === "Reference") {
    trail.push({ label: "Reference" });
  } else if (entry.layer === "Product docs" && entry.section !== "Reference") {
    trail.push({ label: entry.section });
  } else if (entry.kind === "guide") {
    trail.push({ label: "Screenshot guides" });
  }
  trail.push({ label: entry.label });
  return trail;
}

export type DocsPager = { prev?: DocsNavEntry; next?: DocsNavEntry };

/** The previous/next pages in reading order. The first page has no prev; the last none next. */
export function docsPager(path: string): DocsPager {
  const index = DOCS_NAV.findIndex((entry) => entry.path === path);
  if (index === -1) return {};
  return {
    prev: index > 0 ? DOCS_NAV[index - 1] : undefined,
    next: index < DOCS_NAV.length - 1 ? DOCS_NAV[index + 1] : undefined,
  };
}

/** The screenshot guides a product page links to (its own curated list). */
export function relatedGuides(path: string): DocsNavEntry[] {
  const entry = docsEntry(path);
  if (!entry || entry.kind === "guide") return [];
  const out: DocsNavEntry[] = [];
  for (const guidePath of entry.guides) {
    const guide = docsEntry(guidePath);
    if (guide) out.push(guide);
  }
  return out;
}

/** The product pages that link to a guide — the reverse of `guides`, so a guide is never a dead end. */
export function relatedProducts(path: string): DocsNavEntry[] {
  const entry = docsEntry(path);
  if (!entry || entry.kind !== "guide") return [];
  return DOCS_NAV.filter((candidate) => candidate.kind !== "guide" && candidate.guides.includes(path));
}
